using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

// Binding of docs/features/checkout-pricing/discount/discount.feature.
// Platinum has no test on purpose: the business has not decided its reduction (see the test plan, "Not decided").
public class DiscountAcceptanceTests
{
    private static int Charged(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    [Fact]
    // Bronze customer is charged the Bronze price
    public void S1_BronzeCustomerIsCharged9500CentsOn10000()
        => Assert.Equal(9500, Charged(LoyaltyTier.Bronze, 10000));

    [Fact]
    // Silver customer is charged the Silver price
    public void S2_SilverCustomerIsCharged9000CentsOn10000()
        => Assert.Equal(9000, Charged(LoyaltyTier.Silver, 10000));

    [Fact]
    // Gold customer is charged the Gold price
    public void S3_GoldCustomerIsCharged8500CentsOn10000()
        => Assert.Equal(8500, Charged(LoyaltyTier.Gold, 10000));

    [Fact]
    // Bronze customer's reduction lands on a whole cent in their favour
    public void S4_BronzeCustomerIsCharged7CentsOn7()
        => Assert.Equal(7, Charged(LoyaltyTier.Bronze, 7));
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --no-restore 2>&1 | tail -30

